// ═══ JORNADA DO PACIENTE + RETENÇÃO REAL (atendimentos do Doctoralia, sem valores) ═══
// Guarda só: paciente, terapeuta, data e estado (R=realizada, P=programada, F=faltou).
// Regra: "parou" = sem sessão realizada há mais de 45 dias e sem nada agendado.
const JR_KEY='cinpsi_jornada', JR_PARA=45;
function jrLoad(){ const d=load(JR_KEY); return d&&Array.isArray(d.rows)?d:{rows:[]}; }
function jrNz(s){ return String(s==null?'':s).normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/\s+/g,' ').trim(); }
function jrHoje(){ const d=new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
function jrDias(a,b){ return Math.round((Date.parse(b)-Date.parse(a))/864e5); }
function jrAddD(iso,n){ const d=new Date(Date.parse(iso)+n*864e5); return d.toISOString().slice(0,10); }
function jrAddM(iso,n){ const d=new Date(Date.parse(iso)); d.setUTCMonth(d.getUTCMonth()+n); return d.toISOString().slice(0,10); }
function jrTerNome(esp){
  const e=String(esp||'').trim(); if(!e) return '—';
  if(/licen.a\s+clinpsi/i.test(e)) return 'Leticia';
  return String(normTer(e)).split(' ')[0];
}
function jrData(v){
  if(v instanceof Date){ const d=new Date(v.getTime()+12*36e5); return d.toISOString().slice(0,10); }
  const s=String(v||'').trim(); let m;
  if((m=s.match(/^(\d{2})\/(\d{2})\/(\d{4})/))) return m[3]+'-'+m[2]+'-'+m[1];
  if((m=s.match(/^(\d{4})-(\d{2})-(\d{2})/))) return m[0];
  return null;
}
const JR_NAO_PAC=/^(reservad|bloque|almo[cç]o|reuni[aã]o|folga|f[eé]rias)|teste$|psicopedagoga$|^juliana psico$|^supervis/i;

async function jrImportar(input){
  const f=input.files&&input.files[0]; if(!f) return;
  let rows; try{ rows=await xlsxLerArquivo(f); }catch(e){ toast('Não consegui ler a planilha.'); return; }
  input.value='';
  const hi=rows.findIndex(r=>r.some(c=>jrNz(c)==='paciente')&&r.some(c=>jrNz(c)==='data'));
  if(hi<0){ toast('Não achei as colunas Paciente e Data nessa planilha.'); return; }
  const H=rows[hi].map(jrNz), ix=n=>H.indexOf(n);
  const iP=ix('paciente'),iD=ix('data'),iE=ix('especialista'),iS=ix('servicos'),iT=ix('estado');
  if(iT<0){ toast('A planilha precisa ter a coluna "Estado".'); return; }
  const novas=[]; let dmin=null,dmax=null;
  rows.slice(hi+1).forEach(r=>{
    const nome=String(r[iP]||'').trim(), dt=jrData(r[iD]); if(!nome||!dt) return;
    if(!dmin||dt<dmin) dmin=dt; if(!dmax||dt>dmax) dmax=dt;
    if(iS>=0&&/supervis/i.test(String(r[iS]||''))) return;
    if(JR_NAO_PAC.test(jrNz(nome))) return;
    const st=jrNz(r[iT]); let e=null;
    if(st==='consulta realizada'||st==='em consulta') e='R';
    else if(st==='programado') e='P';
    else if(st==='nao compareceu') e='F';
    if(!e) return;
    novas.push([nome,jrTerNome(r[iE]),dt,e]);
  });
  if(!novas.length){ toast('Nenhum atendimento válido encontrado.'); return; }
  const old=jrLoad();
  const mant=(old.rows||[]).filter(r=>r[2]<dmin||r[2]>dmax);
  const all=mant.concat(novas);
  store(JR_KEY,{rows:all,desde:old.desde&&old.desde<dmin?old.desde:dmin,ate:old.ate&&old.ate>dmax?old.ate:dmax,importadoEm:jrHoje()});
  toast('✓ '+novas.length+' atendimentos importados ('+fmtDate(dmin)+' a '+fmtDate(dmax)+').');
  showView('jornada');
}

function jrTers(){
  const c={}; jrLoad().rows.forEach(r=>{ if(r[3]==='R') c[r[1]]=(c[r[1]]||0)+1; });
  return Object.keys(c).filter(t=>c[t]>=5&&t!=='—').sort((a,b)=>c[b]-c[a]);
}

// Jornada de cada paciente (opcionalmente só com um terapeuta)
function jrCalc(ter){
  const D=jrLoad(); if(!D.rows.length) return null;
  const hoje=jrHoje(), limCens=jrAddD(D.desde||'2000-01-01',JR_PARA);
  const m=new Map();
  D.rows.forEach(([nome,t,dt,e])=>{
    if(ter&&t!==ter) return;
    const k=jrNz(nome); let o=m.get(k);
    if(!o){ o={nome,ters:{},first:null,last:null,n:0,faltas:0,prox:null,meses:{}}; m.set(k,o); }
    if(e==='R'){
      o.n++; o.ters[t]=(o.ters[t]||0)+1;
      if(!o.first||dt<o.first) o.first=dt; if(!o.last||dt>o.last) o.last=dt;
      const ym=dt.slice(0,7); o.meses[ym]=(o.meses[ym]||0)+1;
    } else if(e==='P'){ if(dt>=hoje&&(!o.prox||dt<o.prox)) o.prox=dt; }
    else if(e==='F') o.faltas++;
  });
  const lista=[];
  m.forEach(o=>{
    if(!o.n){ if(o.prox){ o.sit='agendado'; o.meses_t=0; o.dias=null; o.cens=false; lista.push(o);} return; }
    o.dias=jrDias(o.last,hoje);
    o.sit=(o.prox||o.dias<=JR_PARA)?'ativo':'parou';
    o.cens=o.first<=limCens;
    const fim=o.sit==='ativo'?hoje:o.last;
    o.meses_t=jrDias(o.first,fim)/30.4375;
    lista.push(o);
  });
  return {lista,hoje,desde:D.desde,ate:D.ate};
}

function jrRetencao(ter){
  const J=jrCalc(ter); if(!J) return null;
  const hoje=J.hoje;
  const calc=N=>{
    const base=J.lista.filter(p=>p.n>0&&!p.cens&&jrAddM(p.first,N)<=hoje);
    const ok=base.filter(p=>p.last>=jrAddM(p.first,N)||p.prox);
    return {p:base.length?Math.round(ok.length/base.length*100):0,b:base.length};
  };
  const r1=calc(1),r3=calc(3),r6=calc(6);
  const b1=J.lista.filter(p=>p.n>0&&!p.cens&&jrAddM(p.first,1)<=hoje);
  return {ret1:r1.p,base1:r1.b,ret3:r3.p,base3:r3.b,ret6:r6.p,base6:r6.b,
          umaSessao:b1.filter(p=>p.n===1).length,baseUma:b1.length,fonte:'jornada'};
}

const calcRetencao=function(ter){
  const r=jrRetencao(ter===undefined?(window._jrTer||''):ter);
  return r||calcRetencaoOld();
};

function jrSetTer(v){ window._jrTer=v||''; showView(_currentView); }
function jrSelTer(sel){
  return '<select onchange="jrSetTer(this.value)" style="margin-left:auto;font-size:12px;padding:4px 8px;border:1px solid var(--border);border-radius:8px;background:#fff;color:var(--text)"><option value="">Todos os terapeutas</option>'
    +jrTers().map(t=>'<option value="'+esc(t)+'"'+(sel===t?' selected':'')+'>'+esc(t)+'</option>').join('')+'</select>';
}
function jrRingHTML(p,l,b,cor){
  const C=2*Math.PI*42;
  return '<div><div class="cx-ring"><svg viewBox="0 0 104 104"><circle cx="52" cy="52" r="42" fill="none" stroke="#EDF0F5" stroke-width="9"/><circle cx="52" cy="52" r="42" fill="none" stroke="'+cor+'" stroke-width="9" stroke-linecap="round" stroke-dasharray="'+C.toFixed(1)+'" stroke-dashoffset="'+(C*(1-Math.min(b?p:0,100)/100)).toFixed(1)+'"/></svg><b>'+(b?p+'%':'—')+'</b></div><div class="cx-ring-t">'+l+'</div><div class="cx-ring-s">'+b+' pacientes avaliados'+(b>0&&b<10?' · amostra pequena':'')+'</div></div>';
}
function jrRetHTML(ret){
  if(!ret) return '<div class="cx-empty">Sem dados.</div>';
  return '<div class="cx-rings">'+jrRingHTML(ret.ret1,'Retidos após 1 mês',ret.base1,'#1E6B3A')+jrRingHTML(ret.ret3,'Retidos após 3 meses',ret.base3,'#15558A')+jrRingHTML(ret.ret6,'Retidos após 6 meses',ret.base6,'#B2680E')+'</div>'
    +jrNotaRet(ret);
}
function jrNotaRet(ret){
  if(!ret) return '';
  if(ret.fonte==='jornada') return ret.baseUma?'<div style="text-align:center;font-size:12px;color:var(--text2);margin-top:10px">'+ret.umaSessao+' de '+ret.baseUma+' pacientes novos ('+Math.round(ret.umaSessao/ret.baseUma*100)+'%) fizeram só 1 sessão · <a href="#" onclick="showView(\'jornada\');return false" style="color:var(--accent)">ver jornada</a></div>':'';
  return '<div style="text-align:center;font-size:11.5px;color:var(--text3);margin-top:10px">Estimativa pelo cadastro. Para o número real, importe os atendimentos em <a href="#" onclick="showView(\'jornada\');return false" style="color:var(--accent)">Jornada do paciente</a>.</div>';
}

// ── Tela ──────────────────────────────────────────────────
window._jrF=window._jrF||{q:'',sit:'',ord:'meses'};
function renderJornada(c){
  const D=jrLoad();
  const acts=document.getElementById('topbar-actions');
  if(acts) acts.innerHTML='<button class="btn-primary" onclick="document.getElementById(\'jr-file\').click()">⬆ Importar atendimentos</button><input type="file" id="jr-file" accept=".xlsx,.xls,.csv" style="display:none" onchange="jrImportar(this)">';
  if(!D.rows.length){
    c.innerHTML='<div class="data-table" style="padding:28px;text-align:center"><div class="section-title">Jornada do paciente</div><p style="color:var(--text2);max-width:520px;margin:8px auto 16px;line-height:1.6">Importe a planilha de consultas do Doctoralia (idealmente os últimos 12 meses). O sistema usa só paciente, terapeuta, data e estado do atendimento; valores são ignorados.</p><button class="btn-primary" onclick="document.getElementById(\'jr-file\').click()">⬆ Importar atendimentos</button></div>';
    return;
  }
  c.innerHTML='<div style="font-size:12px;color:var(--text3);margin-bottom:12px">Atendimentos de '+fmtDate(D.desde)+' a '+fmtDate(D.ate)+' · importado em '+fmtDate(D.importadoEm)+' · "parou" = sem sessão há mais de '+JR_PARA+' dias e nada agendado.</div>'
   +'<div id="jr-kpis"></div>'
   +'<div class="cx-card" style="margin-bottom:16px"><div class="cx-card-h"><h2>Retenção</h2><span id="jr-retsel" style="margin-left:auto"></span></div><div id="jr-ret"></div></div>'
   +'<div class="data-table" style="padding:14px 16px"><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;align-items:center">'
   +'<input id="jr-q" placeholder="Buscar paciente…" oninput="jrSetF(\'q\',this.value)" style="flex:1;min-width:180px;padding:7px 10px;border:1px solid var(--border);border-radius:8px;font-size:13px">'
   +'<select id="jr-sit" onchange="jrSetF(\'sit\',this.value)" style="padding:7px 10px;border:1px solid var(--border);border-radius:8px;font-size:13px;background:#fff"><option value="">Todas as situações</option><option value="ativo">Em tratamento</option><option value="parou">Parou</option><option value="agendado">1ª sessão agendada</option></select>'
   +'<select id="jr-ord" onchange="jrSetF(\'ord\',this.value)" style="padding:7px 10px;border:1px solid var(--border);border-radius:8px;font-size:13px;background:#fff"><option value="meses">Maior tempo em tratamento</option><option value="mesesAsc">Menor tempo em tratamento</option><option value="recente">Última sessão mais recente</option><option value="antiga">Última sessão mais antiga</option><option value="nome">Nome (A–Z)</option></select></div>'
   +'<div id="jr-lista"></div></div>';
  document.getElementById('jr-sit').value=window._jrF.sit;
  document.getElementById('jr-ord').value=window._jrF.ord;
  document.getElementById('jr-q').value=window._jrF.q;
  jrRefresh();
}
function jrSetF(k,v){ window._jrF[k]=v; jrLista(); }
function jrRefresh(){
  const ter=window._jrTer||'';
  const sel=document.getElementById('jr-retsel'); if(sel) sel.innerHTML=jrSelTer(ter);
  const r=document.getElementById('jr-ret'); if(r) r.innerHTML=jrRetHTML(jrRetencao(ter));
  jrLista();
}
function jrMesLabel(ym){ const n=['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez']; return n[+ym.slice(5,7)-1]+'/'+ym.slice(2,4); }
function jrToggle(i){ const e=document.getElementById('jr-x-'+i); if(e) e.style.display=e.style.display==='none'?'':'none'; }
function jrLista(){
  const ter=window._jrTer||'', F=window._jrF;
  const J=jrCalc(ter); const box=document.getElementById('jr-lista'); const kp=document.getElementById('jr-kpis'); if(!box||!J) return;
  const L=J.lista;
  const at=L.filter(p=>p.sit==='ativo').length, pa=L.filter(p=>p.sit==='parou');
  const perm=pa.filter(p=>!p.cens).map(p=>p.meses_t).sort((a,b)=>a-b);
  const med=perm.length?perm[Math.floor(perm.length/2)]:null;
  const uma=pa.filter(p=>p.n===1).length;
  if(kp) kp.innerHTML='<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px">'
    +'<div class="stat-card"><div class="stat-label">Em tratamento</div><div class="stat-value">'+at+'</div></div>'
    +'<div class="stat-card"><div class="stat-label">Pararam</div><div class="stat-value">'+pa.length+'</div></div>'
    +'<div class="stat-card"><div class="stat-label">Permanência típica de quem parou</div><div class="stat-value">'+(med==null?'—':med.toFixed(1).replace('.',',')+' m')+'</div></div>'
    +'<div class="stat-card"><div class="stat-label">Pararam após 1 sessão</div><div class="stat-value">'+uma+'</div></div></div>';
  const q=jrNz(F.q);
  let rows=L.filter(p=>(!F.sit||p.sit===F.sit)&&(!q||jrNz(p.nome).includes(q)));
  const o=F.ord;
  rows.sort((a,b)=>o==='nome'?a.nome.localeCompare(b.nome):o==='mesesAsc'?a.meses_t-b.meses_t:o==='recente'?(b.last||'').localeCompare(a.last||''):o==='antiga'?(a.last||'9').localeCompare(b.last||'9'):b.meses_t-a.meses_t);
  const pill=p=>p.sit==='ativo'?'<span style="background:#D1FAE5;color:#065F46;padding:2px 9px;border-radius:20px;font-size:11.5px">Em tratamento</span>'
    :p.sit==='parou'?'<span style="background:#FEE2E2;color:#991B1B;padding:2px 9px;border-radius:20px;font-size:11.5px">Parou há '+p.dias+' d</span>'
    :'<span style="background:#DBEAFE;color:#1E40AF;padding:2px 9px;border-radius:20px;font-size:11.5px">1ª sessão agendada</span>';
  const hoje=J.hoje;
  const body=rows.map((p,i)=>{
    const ts=Object.keys(p.ters).sort((a,b)=>p.ters[b]-p.ters[a]).join(' · ')||'—';
    let cells='';
    if(p.first){ let ym=p.first.slice(0,7); const fim=hoje.slice(0,7); let g=0;
      while(ym<=fim&&g++<60){ const n=p.meses[ym]||0; cells+='<div title="'+n+' sessões" style="min-width:46px;text-align:center;padding:4px 2px;border-radius:6px;font-size:11px;background:'+(n?'rgba(30,107,58,'+Math.min(.18+n*.1,.85)+')':'#F1F0EC')+';color:'+(n>=5?'#fff':'var(--text)')+'"><div style="font-size:10px;opacity:.75">'+jrMesLabel(ym)+'</div><b>'+n+'</b></div>';
        const d=new Date(Date.parse(ym+'-01')); d.setUTCMonth(d.getUTCMonth()+1); ym=d.toISOString().slice(0,7); } }
    return '<tr onclick="jrToggle('+i+')" style="cursor:pointer;border-bottom:1px solid var(--border)">'
      +'<td style="padding:8px"><strong>'+esc(p.nome)+'</strong>'+(p.faltas?'<div style="font-size:10.5px;color:var(--text3)">'+p.faltas+' falta'+(p.faltas>1?'s':'')+'</div>':'')+'</td>'
      +'<td style="padding:8px;font-size:12.5px">'+esc(ts)+'</td>'
      +'<td style="padding:8px;font-size:12.5px;white-space:nowrap">'+(p.first?fmtDate(p.first):'—')+'</td>'
      +'<td style="padding:8px;font-size:12.5px;white-space:nowrap">'+(p.last?fmtDate(p.last):'—')+'</td>'
      +'<td style="padding:8px;font-size:13px;font-weight:600;white-space:nowrap" '+(p.cens?'title="Já estava em tratamento antes do período importado"':'')+'>'+(p.n?(p.cens?'≥ ':'')+p.meses_t.toFixed(1).replace('.',',')+' m':'—')+'</td>'
      +'<td style="padding:8px;text-align:center;font-size:12.5px">'+p.n+'</td>'
      +'<td style="padding:8px">'+pill(p)+'</td>'
      +'<td style="padding:8px;font-size:12.5px;white-space:nowrap">'+(p.prox?fmtDate(p.prox):'—')+'</td></tr>'
      +'<tr id="jr-x-'+i+'" style="display:none"><td colspan="8" style="padding:8px 12px 14px;background:var(--surface2)"><div style="font-size:11.5px;color:var(--text2);margin-bottom:6px">Sessões realizadas por mês</div><div style="display:flex;gap:4px;flex-wrap:wrap">'+(cells||'—')+'</div></td></tr>';
  }).join('');
  box.innerHTML='<div style="font-size:12px;color:var(--text3);margin-bottom:6px">'+rows.length+' paciente'+(rows.length!==1?'s':'')+(ter?' com '+esc(ter):'')+' · clique na linha para ver mês a mês</div>'
    +'<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><thead><tr style="font-size:11px;color:var(--text3);text-align:left;border-bottom:1px solid var(--border)"><th style="padding:8px">Paciente</th><th style="padding:8px">Terapeuta</th><th style="padding:8px">1ª sessão</th><th style="padding:8px">Última</th><th style="padding:8px">Em tratamento</th><th style="padding:8px;text-align:center">Sessões</th><th style="padding:8px">Situação</th><th style="padding:8px">Próxima</th></tr></thead><tbody>'+(body||'<tr><td colspan="8" style="padding:20px;text-align:center;color:var(--text3)">Nenhum paciente encontrado.</td></tr>')+'</tbody></table></div>';
}


function calcRetencaoOld(){
